class Weapon {
    constructor(name, baseDamage) {
        this.name = name;
        this.baseDamage = baseDamage;
    }

    calculateDamage() {
        return this.baseDamage;
    }
}

class Sword extends Weapon {
    constructor(name, baseDamage, sharpness) {
        super(name, baseDamage);
        this.sharpness = sharpness;
    }

    calculateDamage() {
        // Overly complex way to sum two numbers
        return [this.baseDamage, this.sharpness].reduce((total, value) => total + value, 0);
    }
}

class Bow extends Weapon {
    constructor(name, baseDamage, drawStrength) {
        super(name, baseDamage);
        this.drawStrength = drawStrength;
    }

    calculateDamage() {
        // Overly complex way to multiply two numbers
        return [this.baseDamage, this.drawStrength].reduce((total, value) => total * value, 1);
    }
}

// Test cases - do not modify
